    s = sum(r.values())
    r = {k: v/s for k,v in r.items()}
    print(f"iter {e['iteration']}: {e['target_dissimilarity']:.4f}")
    for k,v in sorted(r.items(), key=lambda x:-x[1]):
        print(f"  {k}: {v:.4f}")
    print()
